using System;
using System.IO;
using System.Collections.Generic;
class PassengerRosterTests {
 static int n;static void Check(bool ok,string why){n++;if(!ok)throw new Exception(why);}
 static void Main(string[] args){try{Run(args);Console.WriteLine("PASS PassengerRosterTests "+n);}catch(Exception e){Console.WriteLine("FAIL "+e.Message);Environment.Exit(1);}}
 static void Run(string[] args){
  ContentTuning.ConfigureCatalog(File.ReadAllText(args[0]));string json=ContentTuning.Text("passenger.presets","");var roster=PassengerPresetCatalog.Parse(json);Check(roster.Length==24,"release roster must contain24 authored passengers, actual="+roster.Length);Check((double)ContentJson.Object(ContentJson.Parse(json))["version"]==2,"release default loads version2 individual overrides");Check(ContentJson.Stringify(ContentJson.Parse(File.ReadAllText(args[1])))==ContentJson.Stringify(ContentJson.Parse(json)),"catalog default exactly matches authored roster");
  ContentTuning.UseJson(File.ReadAllText(args[2]));Check(ContentTuning.Text("passenger.presets","")==json,"published profile loads same roster");
  var old=PassengerPresetCatalog.Parse(File.ReadAllText(args[3]));var oldIds=new HashSet<string>();foreach(var p in old)oldIds.Add(p.id);Check(oldIds.Count==12,"explicit preserved old12 fixture");int active=0,newCount=0;
  var all=(PassengerType[])Enum.GetValues(typeof(PassengerType));
  foreach(var definition in roster){if(!oldIds.Contains(definition.id)){newCount++;Check(definition.enabled&&definition.overrides.Length>0&&definition.intro.Length>0,"new authored passenger has real individual content "+definition.id);foreach(var row in definition.overrides)Check(row.value.IndexOf('{')<0&&row.value.IndexOf('}')<0,"authored override contains no unresolved tokens "+definition.id+":"+row.id);}if(!definition.enabled||definition.weight<=0){Check(definition.id=="routechecking","only removed route checking preset disabled");continue;}active++;
   PassengerBehaviorState p=null;string seed=null;var pool=(PassengerType)Enum.Parse(typeof(PassengerType),definition.pool);for(int i=0;i<1024;i++){string candidate="roster-candidate-"+i;var picked=PassengerBehaviorState.CreateConfigured(candidate,pool,all,null);if(picked.PresetId==definition.id){p=picked;seed=candidate;break;}}Check(p!=null,"weighted default selector reaches "+definition.id);p.Validate();Check(p.PresetName==definition.name&&p.Pool==pool&&p.PresetOverrides.Length==definition.overrides.Length,"selected identity and frozen content "+definition.id);
   if(definition.intro.Length>0)Check(p.Dialogue.Contains(definition.intro),"actual first dialogue contains authored intro "+definition.id);
   var restricted=PassengerBehaviorState.CreateConfigured(seed,pool,new PassengerType[0],null);Check(p.RepresentativeType==PassengerType.General?restricted.PresetId==definition.id:restricted.Type==PassengerType.General&&restricted.PresetId==null,"unavailable representative safely falls back without dropping traits "+definition.id);
   if(p.Type==PassengerType.Luggage||p.Type==PassengerType.MuddyLuggage){var refused=p.Copy();int refusal=p.Type==PassengerType.Luggage?1:2;Check(refused.Respond(refusal,true)&&refused.BoardingReady&&refused.WorkRemaining==0,"refusal adds no unsupported loading/self-storage work "+definition.id);Check(refused.Board()&&refused.Arrive()&&refused.UnloadRemaining==0&&refused.Finish(true)&&refused.DirtEvents.Length==0,"refused cargo stays absent at actual exit "+definition.id);}
   if(p.Type==PassengerType.Food)Check(p.Respond(1,true),"food actual permission "+definition.id);else if(p.HasChoice)Check(p.Respond(0,true),"actual action choice "+definition.id);
   if(p.Choice>=0){var ledger=new ChoiceEffectLedger();ledger.Select("roster-choice",ChoiceEffectDefinition.Read("type."+p.Type+"."+p.Choice,p.Content),50,20);ledger.Validate(p.Content);Check(ledger.entries.Count==1,"individual action effects execute and validate "+definition.id);}
   if(p.PreparationRemaining>0)p.Advance(p.PreparationRemaining,true,false,0,100);Check(p.Board(),"actual preparation allows boarding "+definition.id);p.BindEffectTrip("trip-"+definition.id);p.Advance(30,false,true,.6f,100);p=p.Copy();p.Validate();Check(p.PresetId==definition.id,"active passenger copy retains selected preset "+definition.id);
   if(p.IsDrunk){var drunk=DrunkRideState.CreateAssignedDrunk(seed,p.Content);drunk.Validate();Check(drunk.IsDrunk,"drunk pool retains separate care module "+definition.id);}
   Check(p.Arrive(),"arrival accepted "+definition.id);if(p.UnloadRemaining>0)p.Advance(p.UnloadRemaining,true,false,1,100);Check(p.Finish(true),"real module finishes after required work "+definition.id);p.Validate();var care=new VehicleCare();foreach(var dirt in p.DirtEvents)care.Soil(dirt.Id,dirt.Amount);int clean=care.Cleanliness;foreach(var dirt in p.Copy().DirtEvents)care.Soil(dirt.Id,dirt.Amount);Check(care.Cleanliness==clean,"roster dirt replay is idempotent "+definition.id);
  }
  Check(active==23&&newCount==12,"release preserves twelve and adds twelve with23 enabled");Check(!ContentTuning.Flag("request.ShortRoad.enabled",true)&&ContentTuning.Int("request.ShortRoad.weight",1)==0&&!ContentTuning.Flag("request.RouteAdvice.enabled",true)&&ContentTuning.Int("request.RouteAdvice.weight",1)==0,"short/fast requests excluded by enabled and weight");Check(ContentTuning.Int("type.RouteChecking.weight",1)==0,"legacy route pool not drawn");Check(ContentTuning.Flag("request.LargeRoad.enabled",false)&&ContentTuning.Flag("request.Eta.enabled",false),"large road and ETA stay available");Check(ContentTuning.Int("schedule.count0",-1)==25&&ContentTuning.Int("schedule.count1",-1)==60&&ContentTuning.Int("schedule.count2",-1)==15,"release request count weights25/60/15");
  var kinds=(RequestKind[])Enum.GetValues(typeof(RequestKind));int[] counts=new int[3];for(int i=0;i<1500;i++){var schedule=PassengerRequestSchedule.Create("release-route-"+i,kinds).Capture();counts[schedule.slots.Length]++;foreach(var slot in schedule.slots)Check(slot.kind!=RequestKind.ShortRoad&&slot.kind!=RequestKind.RouteAdvice,"disabled short/fast request never scheduled");}Check(counts[0]>0&&counts[1]>0&&counts[2]>0,"all authored request counts exercised");
  var empty=PassengerBehaviorState.CreateConfigured("disabled",PassengerType.RouteChecking,all,null);Check(empty.Type==PassengerType.General&&empty.PresetId==null,"disabled route pool immutable ordinary fallback");
 }
}
